local log_file = io.open("D:/Projects/hacking/Parodius/parodius_census.txt", "a")
local function flog(s)
  if log_file then log_file:write(s .. "\n"); log_file:flush() end
end
flog("=== run start ===")

-- ---------------- fallthrough monitor ----------------
local frames = 0
local ndec, nvc = 0, 0
local seen = {}

local function rd(a)  return emu.read(a, emu.memType.pceMemory, false) end
local function rd16(a) return emu.read16(a, emu.memType.pceMemory, false) end

local function on_dec()
  ndec = ndec + 1
  local ptr = rd16(0x2008)
  local key = string.format("D%02X%02X%04X", rd(ptr), rd(ptr + 1), rd16(ptr + 4))
  if not seen[key] then
    seen[key] = true
    flog(string.format(
      "DEC   F=%d stage=$%02X bank=$%02X p1=$%02X dst=$%04X.w src=$%04X",
      frames, rd(0x2093), rd(ptr), rd(ptr + 1), rd16(ptr + 2), rd16(ptr + 4)))
  end
end

local function on_vcopy()
  nvc = nvc + 1
  local ptr = rd16(0x2008)
  local key = string.format("V%04X%04X", rd16(ptr + 2), rd16(ptr + 4))
  if not seen[key] then
    seen[key] = true
    flog(string.format(
      "VCOPY F=%d stage=$%02X src=$%04X.w dst=$%04X.w words=%d",
      frames, rd(0x2093), rd16(ptr + 2), rd16(ptr + 4), rd(ptr + 6) * 16))
  end
end

emu.addMemoryCallback(on_dec, emu.callbackType.exec, 0xC25C, 0xC25C,
                      emu.cpuType.pce, emu.memType.pceMemory)
emu.addMemoryCallback(on_vcopy, emu.callbackType.exec, 0xC168, 0xC168,
                      emu.cpuType.pce, emu.memType.pceMemory)

