local function in_gap(off)
  local lo, hi = 1, #gaps
  while lo <= hi do
    local mid = math.floor((lo + hi) / 2)
    local g = gaps[mid]
    if off < g[1] then hi = mid - 1
    elseif off >= g[2] then lo = mid + 1
    else return true end
  end
  return false
end

local hits = 0
local paused_once = {}

local function on_access(kind)
  return function(addr, value)
    if not in_gap(addr) then return end
    hits = hits + 1
    local ok, st = pcall(emu.getState)
    local pc = (ok and st and st["cpu.pc"]) or 0
    local line = string.format("%s off=$%06X (bank $%02X) val=$%02X pc=$%04X",
        kind, addr, math.floor(addr / 8192), value or -1, pc)
    flog(line)
    emu.log(line)
    if not paused_once[addr - (addr % 64)] then
      paused_once[addr - (addr % 64)] = true
      emu.breakExecution()
    end
  end
end

